using System;
using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
namespace SpatialWallpaper.Blueprint {
 // Bounded canonical data returned by the trusted import helper; no source NBT
 // tags or executable content enter the Unity scene process through this file.
 public static class BlueprintDocumentTransport {
  static void Text(BinaryWriter writer,string value){byte[] bytes=Encoding.UTF8.GetBytes(value??"");if(bytes.Length>8192)throw new BlueprintImportException("document-text-budget");writer.Write((ushort)bytes.Length);writer.Write(bytes);}
  static string Text(BinaryReader reader){int count=reader.ReadUInt16();if(count>8192)throw new BlueprintImportException("document-text-budget");var bytes=reader.ReadBytes(count);if(bytes.Length!=count)throw new EndOfStreamException();return Encoding.UTF8.GetString(bytes);}
  public static byte[] Write(BlueprintDocument d){using(var raw=new MemoryStream()){using(var w=new BinaryWriter(raw,Encoding.UTF8,true)){w.Write(0x31445042);foreach(int n in new[]{d.Width,d.Height,d.Length,d.DataVersion,d.EntityCount,d.BlockEntityCount,d.Palette.Count})w.Write(n);foreach(long n in new[]{d.OriginX,d.OriginY,d.OriginZ})w.Write(n);Text(w,d.SourceHash);Text(w,d.Format);Text(w,d.Name!=null&&d.Name.Length>128?d.Name.Substring(0,128):d.Name);foreach(var state in d.Palette)Text(w,state.Key);foreach(int index in d.Indices)w.Write(checked((ushort)index));}byte[] bytes=raw.ToArray();if(bytes.Length>NbtInput.MaxDecodedBytes-32)throw new BlueprintImportException("document-budget");using(var output=new MemoryStream()){using(var gzip=new GZipStream(output,CompressionLevel.Fastest,true)){gzip.Write(bytes,0,bytes.Length);using(var sha=SHA256.Create()){var digest=sha.ComputeHash(bytes);gzip.Write(digest,0,digest.Length);}}return output.ToArray();}}}
  public static BlueprintDocument Read(byte[] input){try{if(input==null||input.Length>NbtInput.MaxInputBytes)throw new BlueprintImportException("document-budget");byte[] bytes;using(var gzip=new GZipStream(new MemoryStream(input,false),CompressionMode.Decompress))using(var output=new MemoryStream()){var buffer=new byte[32768];int count;while((count=gzip.Read(buffer,0,buffer.Length))>0){if(output.Length+count>NbtInput.MaxDecodedBytes)throw new BlueprintImportException("document-budget");output.Write(buffer,0,count);}bytes=output.ToArray();}if(bytes.Length<64)throw new BlueprintImportException("document-truncated");using(var sha=SHA256.Create()){var digest=sha.ComputeHash(bytes,0,bytes.Length-32);for(int i=0;i<32;i++)if(bytes[bytes.Length-32+i]!=digest[i])throw new BlueprintImportException("document-digest");}
   using(var r=new BinaryReader(new MemoryStream(bytes,0,bytes.Length-32,false))){if(r.ReadInt32()!=0x31445042)throw new BlueprintImportException("document-version");int width=r.ReadInt32(),height=r.ReadInt32(),length=r.ReadInt32();var d=new BlueprintDocument(width,height,length){DataVersion=r.ReadInt32(),EntityCount=r.ReadInt32(),BlockEntityCount=r.ReadInt32()};int count=r.ReadInt32();if(count<1||count>NbtInput.MaxPalette||d.EntityCount<0||d.EntityCount>NbtInput.MaxTags||d.BlockEntityCount<0||d.BlockEntityCount>NbtInput.MaxTags)throw new BlueprintImportException("document-budget");d.OriginX=r.ReadInt64();d.OriginY=r.ReadInt64();d.OriginZ=r.ReadInt64();d.SourceHash=Text(r);d.Format=Text(r);d.Name=Text(r);if(d.SourceHash.Length!=64)throw new BlueprintImportException("document-identity");int[] map=new int[count];for(int i=0;i<count;i++)map[i]=d.Intern(BlockState.Parse(Text(r)));if((long)d.Indices.Length*2!=r.BaseStream.Length-r.BaseStream.Position)throw new BlueprintImportException("document-indices");for(int i=0;i<d.Indices.Length;i++){int index=r.ReadUInt16();if(index>=count)throw new BlueprintImportException("document-palette");d.Indices[i]=map[index];}d.Finish();return d;}
  }catch(BlueprintImportException){throw;}catch(Exception e)when(e is IOException||e is ArgumentException||e is OverflowException){throw new BlueprintImportException("document-invalid: "+e.Message);}}
 }
}
